export const options = { format: { default: 'json', values: ['json', 'csv'] }, limit: { default: 25 } };
export function formatReport(rows, { format = options.format.default, limit = options.limit.default } = {}) {
  if (!options.format.values.includes(format)) throw new Error('Unsupported format');
  const selected = rows.slice(0, limit);
  return format === 'json' ? JSON.stringify(selected) : ['name', ...selected.map(row => row.name)].join('\n');
}

